(()=>{'use strict';const buttons=[...document.querySelectorAll('[data-catalog-filter]')];buttons.forEach(button=>button.addEventListener('click',()=>{buttons.forEach(item=>item.setAttribute('aria-pressed',String(item===button)));let count=0;document.querySelectorAll('[data-catalog-kind]').forEach(entry=>{entry.hidden=button.dataset.catalogFilter!=='all'&&entry.dataset.catalogKind!==button.dataset.catalogFilter;if(!entry.hidden)count++;});document.querySelector('#catalog-count').textContent=count+' 篇示例文字';}));})();
